import{_ as n,C as s,o as l,c as o,a3 as t,E as r}from"./chunks/framework.bGC-1KKp.js";const b=JSON.parse('{"title":"Séance 3 — La veille technologique","description":"","frontmatter":{"title":"Séance 3 — La veille technologique","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/03-veille-technologique.md","filePath":"modules/01-faisabilite/03-veille-technologique.md"}'),u={name:"modules/01-faisabilite/03-veille-technologique.md"};function d(c,e,g,p,f,h){const i=s("TriSources"),a=s("GrillePrix");return l(),o("div",null,[e[0]||(e[0]=t('<h1 id="seance-3-—-la-veille-technologique" tabindex="-1">Séance 3 — La veille technologique <a class="header-anchor" href="#seance-3-—-la-veille-technologique" aria-label="Permalink to &quot;Séance 3 — La veille technologique&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Trouver de l&#39;information fiable sur le Web et reconnaître une <strong>publicité déguisée en comparatif</strong>.</li><li>Lire une <strong>grille de prix</strong> : ce qui se paie au mois, à l&#39;utilisateur ou à la transaction.</li><li>Préparer l&#39;<strong>essai rigoureux</strong> d&#39;un outil : les mêmes manipulations, dans les mêmes conditions, sur chaque solution.</li><li>Comprendre ce qu&#39;on attend dans l&#39;<strong>évaluation 1</strong>.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour sur le Lab 02 : ce qu&#39;on garde pour l&#39;évaluation 1</td></tr><tr><td style="text-align:left;">18 h 40</td><td style="text-align:left;"><a href="./../../evaluations/evaluation-1">L&#39;énoncé de l&#39;évaluation 1</a></td></tr><tr><td style="text-align:left;">19 h 05</td><td style="text-align:left;">La veille technologique : où chercher, à qui se fier</td></tr><tr><td style="text-align:left;">19 h 20</td><td style="text-align:left;">Activité 1 — Dix sources à classer (en équipe)</td></tr><tr><td style="text-align:left;">19 h 45</td><td style="text-align:left;">Retour en grand groupe</td></tr><tr><td style="text-align:left;">20 h 00</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;">Lire une grille de prix · Activité 2 — Trois outils, trois factures</td></tr><tr><td style="text-align:left;">20 h 45</td><td style="text-align:left;">Essayer un outil de façon rigoureuse</td></tr><tr><td style="text-align:left;">21 h 00</td><td style="text-align:left;">Tirage des questions · <a href="./../../labs/lab03-plan-essai">Lab 03 — Le plan d&#39;essai</a> (en équipe)</td></tr><tr><td style="text-align:left;">21 h 50</td><td style="text-align:left;">Ce qu&#39;il faut avoir fait avant la séance 4</td></tr></tbody></table><hr><h2 id="retour-sur-le-lab-02" tabindex="-1">Retour sur le Lab 02 <a class="header-anchor" href="#retour-sur-le-lab-02" aria-label="Permalink to &quot;Retour sur le Lab 02&quot;">​</a></h2><p>La radiographie du mandat est terminée : vous savez <strong>ce que le projet exige</strong>, <strong>ce qui le limite</strong> et <strong>ce qui pourrait mal tourner</strong>. Ce soir, on ouvre la deuxième moitié du travail d&#39;analyste : <strong>quelles technologies existent</strong> pour répondre à ces besoins ?</p><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Les trois constats de la correction commentée</strong><br><ul class="list-disc pl-5"><li><strong>Les coûts annuels sont partout et personne ne les a chiffrés.</strong> Ce soir, on apprend à les lire dans une grille de prix.</li><li><strong>Viator, Square, Google Workspace et le nom de domaine existent déjà.</strong> Tout outil qu&#39;on regarde doit composer avec eux.</li><li><strong>Le réseau est faible au quai.</strong> Un outil qui fonctionne parfaitement au bureau peut échouer là où on en a besoin. Seul un essai peut le révéler.</li></ul></div><hr><h2 id="l-evaluation-1" tabindex="-1">L&#39;évaluation 1 <a class="header-anchor" href="#l-evaluation-1" aria-label="Permalink to &quot;L&#39;évaluation 1&quot;">​</a></h2><p>L&#39;énoncé complet est sur sa propre page : <strong><a href="./../../evaluations/evaluation-1">Évaluation 1 — Rapport de faisabilité technique : évaluation technique</a></strong>.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li>Un rapport qui <strong>décrit la situation</strong> du projet Aventure Saint-Maurice : exigences, contraintes, risques et <strong>technologies possibles</strong>. Il ne recommande encore rien.</li><li>En équipe, remise le <strong>11 novembre</strong> sur LÉA. 20 % de la note finale, dont 10 % pour le français.</li><li>Le Lab 02 vous a donné les trois premières parties. Les séances 3 et 4 vous donnent la quatrième : les technologies.</li></ul></div><hr><h2 id="la-veille-technologique" tabindex="-1">La veille technologique <a class="header-anchor" href="#la-veille-technologique" aria-label="Permalink to &quot;La veille technologique&quot;">​</a></h2><p>Faire de la veille, c&#39;est <strong>suivre ce qui existe et ce qui change</strong> dans son domaine. Dans un projet, c&#39;est plus précis : on cherche les outils qui pourraient répondre à un besoin, puis on vérifie ce qu&#39;ils valent vraiment.</p><p>Le problème : sur le Web, une bonne partie de l&#39;information sur les outils est écrite par <strong>ceux qui les vendent</strong>, ou par des gens <strong>payés quand vous les achetez</strong>.</p><h3 id="ou-chercher" tabindex="-1">Où chercher <a class="header-anchor" href="#ou-chercher" aria-label="Permalink to &quot;Où chercher&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Type de source</th><th style="text-align:left;">Exemples</th><th style="text-align:left;">À quoi elle sert</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Documentation de référence</strong></td><td style="text-align:left;">MDN Web Docs, W3C, Can I use</td><td style="text-align:left;">Comprendre une technologie, vérifier ce qu&#39;un navigateur supporte</td></tr><tr><td style="text-align:left;"><strong>Organismes officiels</strong></td><td style="text-align:left;">Commission d&#39;accès à l&#39;information, Office québécois de la langue française</td><td style="text-align:left;">Connaître les obligations légales</td></tr><tr><td style="text-align:left;"><strong>Documentation de l&#39;outil</strong></td><td style="text-align:left;">Centre d&#39;aide, page des prix, conditions d&#39;utilisation</td><td style="text-align:left;">Savoir ce que l&#39;outil <strong>prétend</strong> faire, et à quel prix</td></tr><tr><td style="text-align:left;"><strong>Témoignages d&#39;utilisateurs</strong></td><td style="text-align:left;">Forums, Reddit, groupes d&#39;entrepreneurs, sites d&#39;avis</td><td style="text-align:left;">Découvrir les problèmes que le vendeur ne mentionne pas</td></tr><tr><td style="text-align:left;"><strong>Comparatifs</strong></td><td style="text-align:left;">Articles « les 10 meilleurs… », vidéos « j&#39;ai testé… »</td><td style="text-align:left;">Trouver des noms d&#39;outils… et c&#39;est tout, tant qu&#39;on n&#39;a pas vérifié qui paie</td></tr><tr><td style="text-align:left;"><strong>Assistants d&#39;IA</strong></td><td style="text-align:left;">ChatGPT, Copilot, Claude</td><td style="text-align:left;">Trouver des pistes et du vocabulaire. Jamais une source en soi : tout est à vérifier</td></tr></tbody></table><h3 id="les-cinq-questions-a-poser-a-une-source" tabindex="-1">Les cinq questions à poser à une source <a class="header-anchor" href="#les-cinq-questions-a-poser-a-une-source" aria-label="Permalink to &quot;Les cinq questions à poser à une source&quot;">​</a></h3><ol><li><strong>Qui parle ?</strong> Un organisme, un expert identifié, un vendeur, un anonyme ?</li><li><strong>Quand ?</strong> Une page de 2021 sur les prix ou les lois est probablement périmée.</li><li><strong>Qui paie ?</strong> Y a-t-il une commandite, des liens d&#39;affiliation, un bouton « Essai gratuit » à chaque paragraphe ?</li><li><strong>Sur quoi s&#39;appuie-t-elle ?</strong> Des essais décrits, des chiffres, des sources citées… ou des impressions ?</li><li><strong>Est-ce confirmé ailleurs ?</strong> Une information qu&#39;on ne retrouve dans aucune autre source indépendante reste à vérifier.</li></ol><h3 id="reconnaitre-une-publicite-deguisee-en-comparatif" tabindex="-1">Reconnaître une publicité déguisée en comparatif <a class="header-anchor" href="#reconnaitre-une-publicite-deguisee-en-comparatif" aria-label="Permalink to &quot;Reconnaître une publicité déguisée en comparatif&quot;">​</a></h3><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Les indices qui doivent allumer une lumière</strong><br><ul class="list-disc pl-5"><li>Le comparatif est publié <strong>par l&#39;un des outils comparés</strong>… qui arrive premier.</li><li>Les liens vers les outils contiennent <code>?ref=</code>, <code>?aff=</code>, <code>?via=</code> ou <code>partner</code> : l&#39;auteur touche une commission.</li><li>Une phrase en petits caractères : « Nous pouvons recevoir une rémunération… », « Cette vidéo est commanditée par… ».</li><li>Aucun défaut n&#39;est mentionné pour le gagnant, et aucun essai n&#39;est décrit.</li><li>Le texte est le même, à quelques mots près, sur plusieurs sites.</li></ul> Un comparatif publicitaire n&#39;est pas inutile : il donne des <strong>noms d&#39;outils</strong> à explorer. Mais il ne peut jamais servir de preuve dans un rapport. </div><hr><h2 id="activite-1-—-dix-sources-a-classer" tabindex="-1">Activité 1 — Dix sources à classer <a class="header-anchor" href="#activite-1-—-dix-sources-a-classer" aria-label="Permalink to &quot;Activité 1 — Dix sources à classer&quot;">​</a></h2><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (25 min, en équipe)</strong><br> Votre équipe cherche de l&#39;information pour le projet Aventure Saint-Maurice et tombe sur les dix sources ci-dessous. <ol class="list-decimal pl-5"><li>Pour chacune, écrivez votre <strong>justification</strong> en une phrase : quel indice vous a fait trancher ?</li><li>Classez-la : <strong>fiable</strong>, <strong>à vérifier</strong> ou <strong>publicitaire</strong>. La réponse s&#39;affiche après votre choix.</li><li>À la fin, cliquez sur « Copier nos réponses » et collez-les dans le document de votre équipe.</li></ol></div>',26)),r(i),e[1]||(e[1]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> « fiable » ne veut pas dire « vrai pour toujours », et « publicitaire » ne veut pas dire « faux ». Ça veut dire : <strong>quel poids</strong> cette source peut avoir dans un rapport remis à un client. Dans l&#39;évaluation 1, chaque information importante doit pouvoir s&#39;appuyer sur une source fiable ou sur <strong>votre propre essai</strong>.</p><hr><h2 id="lire-une-grille-de-prix" tabindex="-1">Lire une grille de prix <a class="header-anchor" href="#lire-une-grille-de-prix" aria-label="Permalink to &quot;Lire une grille de prix&quot;">​</a></h2><p>Les outils Web se paient rarement « une fois ». Presque tous sont des <strong>abonnements</strong> (on parle de SaaS : <em>Software as a Service</em>), et chacun calcule son prix à sa façon.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Modèle</th><th style="text-align:left;">Comment ça marche</th><th style="text-align:left;">Ce qui fait monter la facture</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Au mois (forfait)</strong></td><td style="text-align:left;">Un montant fixe chaque mois, peu importe l&#39;usage</td><td style="text-align:left;">Le forfait supérieur, quand on dépasse une limite (nombre de réservations, de pages, d&#39;espace)</td></tr><tr><td style="text-align:left;"><strong>À l&#39;utilisateur</strong></td><td style="text-align:left;">Un montant par personne qui a un accès</td><td style="text-align:left;">Chaque employé ajouté : l&#39;accueil, les guides, le comptable</td></tr><tr><td style="text-align:left;"><strong>À la transaction (commission)</strong></td><td style="text-align:left;">Un pourcentage ou un montant sur chaque vente</td><td style="text-align:left;">Le succès : plus l&#39;entreprise vend, plus elle paie</td></tr><tr><td style="text-align:left;"><strong>Gratuit… avec limites</strong></td><td style="text-align:left;">Un forfait de départ gratuit</td><td style="text-align:left;">Les fonctions essentielles réservées aux forfaits payants, le logo de l&#39;outil affiché</td></tr></tbody></table><h3 id="les-pieges-d-une-grille-de-prix" tabindex="-1">Les pièges d&#39;une grille de prix <a class="header-anchor" href="#les-pieges-d-une-grille-de-prix" aria-label="Permalink to &quot;Les pièges d&#39;une grille de prix&quot;">​</a></h3><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><ul class="list-disc pl-5"><li><strong>Le prix en dollars américains.</strong> 100 $ US, ce n&#39;est pas 100 $ CA.</li><li><strong>« Facturé annuellement ».</strong> Le prix affiché au mois suppose souvent un engagement de 12 mois payé d&#39;avance. Au mois, c&#39;est plus cher.</li><li><strong>Les modules payants.</strong> La fonction dont vous avez besoin (synchronisation avec Viator, deuxième langue, décharge) est souvent un supplément.</li><li><strong>Les frais de paiement.</strong> Le service de paiement prend sa part (souvent autour de 3 % par transaction) en plus de l&#39;outil.</li><li><strong>Les taxes.</strong> TPS et TVQ s&#39;ajoutent presque toujours au prix affiché.</li><li><strong>La saison.</strong> Une entreprise saisonnière paie-t-elle 12 mois pour en utiliser 8 ? Peut-on suspendre l&#39;abonnement l&#39;hiver ?</li></ul></div><h2 id="activite-2-—-trois-outils-trois-factures" tabindex="-1">Activité 2 — Trois outils, trois factures <a class="header-anchor" href="#activite-2-—-trois-outils-trois-factures" aria-label="Permalink to &quot;Activité 2 — Trois outils, trois factures&quot;">​</a></h2><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (25 min, en équipe)</strong><br> Trois outils de réservation <strong>fictifs</strong>, trois façons de calculer le prix. Avec les hypothèses fournies, calculez ce que chacun coûterait à Aventure Saint-Maurice <strong>pour une année</strong>. Écrivez vos réponses, puis cliquez sur « Vérifier ». </div>',9)),r(a),e[2]||(e[2]=t('<hr><h2 id="essayer-un-outil-de-facon-rigoureuse" tabindex="-1">Essayer un outil de façon rigoureuse <a class="header-anchor" href="#essayer-un-outil-de-facon-rigoureuse" aria-label="Permalink to &quot;Essayer un outil de façon rigoureuse&quot;">​</a></h2><p>Lire la documentation d&#39;un outil, c&#39;est savoir ce qu&#39;il <strong>prétend</strong> faire. L&#39;essayer, c&#39;est savoir ce qu&#39;il <strong>fait</strong>, et combien d&#39;efforts ça demande. À la séance 4, chaque équipe essaiera deux ou trois outils. Pour que la comparaison soit juste, l&#39;essai se prépare <strong>ce soir</strong>.</p><h3 id="les-regles-d-un-essai-rigoureux" tabindex="-1">Les règles d&#39;un essai rigoureux <a class="header-anchor" href="#les-regles-d-un-essai-rigoureux" aria-label="Permalink to &quot;Les règles d&#39;un essai rigoureux&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Règle</th><th style="text-align:left;">Pourquoi</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Les mêmes manipulations sur chaque outil</strong>, dans le même ordre</td><td style="text-align:left;">Sinon, on compare des pommes et des oranges.</td></tr><tr><td style="text-align:left;"><strong>Des scénarios tirés du mandat</strong>, pas de la démonstration du vendeur</td><td style="text-align:left;">« Une famille de 4 réserve la via ferrata pour samedi 10 h », pas « créer un produit test ».</td></tr><tr><td style="text-align:left;"><strong>On note le temps</strong> que prend chaque manipulation</td><td style="text-align:left;">« Facile » ne veut rien dire. « 4 minutes, sans aide » veut dire quelque chose.</td></tr><tr><td style="text-align:left;"><strong>On prend des captures d&#39;écran</strong></td><td style="text-align:left;">Elles serviront de preuves dans le rapport.</td></tr><tr><td style="text-align:left;"><strong>On note ce qui ne fonctionne pas</strong> ou ce qui est bloqué dans la version d&#39;essai</td><td style="text-align:left;">Un échec est un résultat aussi important qu&#39;un succès.</td></tr><tr><td style="text-align:left;"><strong>On essaie des deux côtés</strong> : le client qui réserve, et Mélanie qui gère</td><td style="text-align:left;">Un outil peut être agréable pour l&#39;un et pénible pour l&#39;autre.</td></tr><tr><td style="text-align:left;"><strong>On essaie sur téléphone</strong>, et avec un réseau lent</td><td style="text-align:left;">La majorité des clients réserveront sur leur téléphone. Le guide sera au quai.</td></tr><tr><td style="text-align:left;"><strong>On vérifie comment on en sort</strong> : exporter les données, fermer le compte</td><td style="text-align:left;">Un outil facile à adopter et impossible à quitter est un risque.</td></tr></tbody></table><h3 id="ouvrir-un-compte-d-essai-sans-se-faire-pieger" tabindex="-1">Ouvrir un compte d&#39;essai sans se faire piéger <a class="header-anchor" href="#ouvrir-un-compte-d-essai-sans-se-faire-pieger" aria-label="Permalink to &quot;Ouvrir un compte d&#39;essai sans se faire piéger&quot;">​</a></h3><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><ul class="list-disc pl-5"><li><strong>Vérifiez la durée de l&#39;essai avant de l&#39;ouvrir.</strong> Il n&#39;y a pas de cours le 14 octobre : un essai de 14 jours ouvert ce soir sera expiré le 21. Si l&#39;essai est court, notez-le et ouvrez le compte <strong>la veille de la séance 4</strong>.</li><li><strong>Utilisez une adresse courriel d&#39;équipe</strong> que tous les membres peuvent consulter, et notez les accès dans votre dossier partagé.</li><li><strong>N&#39;entrez aucune carte de crédit.</strong> Si un outil l&#39;exige pour l&#39;essai, notez-le comme constat et passez au suivant, ou demandez à l&#39;enseignant.</li><li><strong>N&#39;entrez aucun vrai renseignement personnel</strong>, ni le vôtre ni celui d&#39;un client. Utilisez des données inventées (Loi 25).</li><li><strong>Lisez ce que l&#39;essai ne comprend pas.</strong> Certaines fonctions sont bloquées pendant l&#39;essai : c&#39;est un constat à noter.</li></ul></div><hr><h2 id="les-cinq-questions-techniques" tabindex="-1">Les cinq questions techniques <a class="header-anchor" href="#les-cinq-questions-techniques" aria-label="Permalink to &quot;Les cinq questions techniques&quot;">​</a></h2><p>Chaque équipe reçoit, par tirage, <strong>une</strong> des cinq questions. Elle l&#39;explore en profondeur aux séances 3 et 4, avec des essais. Dans l&#39;évaluation 1, elle traite aussi les quatre autres questions, en survol, à partir de sa propre recherche documentaire.</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">La question</th><th style="text-align:left;">Ce qui la rend difficile dans le mandat</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Q1</strong></td><td style="text-align:left;"><strong>Comment réserver et payer en ligne ?</strong></td><td style="text-align:left;">Places limitées par départ, groupes avec dépôt de 30 %, Viator qui vend les mêmes places, Square à garder, cartes-cadeaux, annulations pour la météo</td></tr><tr><td style="text-align:center;"><strong>Q2</strong></td><td style="text-align:left;"><strong>Comment faire signer la décharge avant l&#39;arrivée ?</strong></td><td style="text-align:left;">Parents qui signent pour les mineurs, questions de santé (Loi 25), texte de l&#39;avocat en français seulement, consultation au quai sans réseau</td></tr><tr><td style="text-align:center;"><strong>Q3</strong></td><td style="text-align:left;"><strong>Sur quelle plateforme construire le site ?</strong></td><td style="text-align:left;">Mélanie doit le modifier seule, compte Wix au nom du neveu, nom de domaine et courriels à ne pas briser, intégration de la réservation</td></tr><tr><td style="text-align:center;"><strong>Q4</strong></td><td style="text-align:left;"><strong>Comment montrer les vidéos sans ralentir le site ?</strong></td><td style="text-align:left;">60 Go de vidéos 4K, vidéo plein écran souhaitée, visiteurs sur téléphone, sous-titres et accessibilité</td></tr><tr><td style="text-align:center;"><strong>Q5</strong></td><td style="text-align:left;"><strong>Comment offrir le site en français et en anglais ?</strong></td><td style="text-align:left;">Charte de la langue française, traduction automatique ou humaine, décharge juridique, outil de réservation à traduire aussi</td></tr></tbody></table><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab03-plan-essai">Lab 03 — Le plan d&#39;essai</a></p><hr><h2 id="avant-la-seance-4-21-octobre" tabindex="-1">Avant la séance 4 (21 octobre) <a class="header-anchor" href="#avant-la-seance-4-21-octobre" aria-label="Permalink to &quot;Avant la séance 4 (21 octobre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 03 dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Ouvrir les comptes d&#39;essai <strong>au bon moment</strong> : ils doivent être actifs le 21 octobre</span></label></li><li><label><input type="checkbox"><span class="check-text">Préparer les données inventées dont vous aurez besoin pour vos scénarios (noms, départs, tarifs)</span></label></li><li><label><input type="checkbox"><span class="check-text">Lire l&#39;énoncé de l&#39;évaluation 1 et noter vos questions</span></label></li><li><label><input type="checkbox"><span class="check-text">Commencer la mise au propre des parties 1 à 3 du rapport à partir du Lab 02</span></label></li></ul>',16))])}const x=n(u,[["render",d]]);export{b as __pageData,x as default};
